@push('scripts')<script>jQuery(function($){let dragged=null;$('#property-gallery').on('dragstart','.gallery-image',function(e){dragged=this;e.originalEvent.dataTransfer.effectAllowed='move';$(this).addClass('opacity-50')}).on('dragover','.gallery-image',function(e){e.preventDefault();if(dragged&&dragged!==this){const box=this.getBoundingClientRect();$(this)[e.originalEvent.clientY>box.top+box.height/2?'after':'before'](dragged)}}).on('dragend','.gallery-image',function(){$('.gallery-image').removeClass('opacity-50')});});</script>@endpush
